package studio.solocamera;

import android.app.*;import android.content.*;import android.graphics.Typeface;import android.os.*;import android.widget.*;
import org.json.*;import java.io.*;import java.net.*;import java.security.*;import java.util.*;import java.util.concurrent.atomic.AtomicBoolean;import java.util.function.Consumer;

/** Opt-in OFL font catalog: pinned HTTPS files, exact byte count and SHA-256 validation. */
final class EditorFontLibrary {
 static JSONArray catalog(Context c){try(InputStream in=c.getAssets().open("optional-fonts.json")){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];for(int n;(n=in.read(b))!=-1;)out.write(b,0,n);return new JSONArray(out.toString("UTF-8"));}catch(Exception e){return new JSONArray();}}
 static File file(Context c,String id){if(!id.matches("[a-z0-9]+"))throw new IllegalArgumentException("Invalid font ID");return new File(new File(c.getFilesDir(),"download-fonts"),id+".ttf");}
 static String displayName(Context c,String value){JSONArray fonts=catalog(c);for(int i=0;i<fonts.length();i++){JSONObject f=fonts.optJSONObject(i);if(f!=null&&value.equals("file:"+file(c,f.optString("id")).getAbsolutePath()))return f.optString("name");}return "Imported font";}
 static void appendInstalled(Context c,List<String> names,List<String> values){JSONArray fonts=catalog(c);for(int i=0;i<fonts.length();i++){JSONObject f=fonts.optJSONObject(i);if(f!=null&&file(c,f.optString("id")).isFile()){names.add(f.optString("name"));values.add("file:"+file(c,f.optString("id")).getAbsolutePath());}}}
 static void show(Activity activity,Consumer<String> applied){LinearLayout content=new LinearLayout(activity);content.setOrientation(LinearLayout.VERTICAL);int pad=(int)(16*activity.getResources().getDisplayMetrics().density);content.setPadding(pad,pad,pad,pad);TextView intro=new TextView(activity);intro.setText("Optional free fonts. Internet is needed only to download. Installed fonts work offline. Each font includes its OFL license.");content.addView(intro);ScrollView scroll=new ScrollView(activity);scroll.addView(content);AlertDialog list=new AlertDialog.Builder(activity).setTitle("Font library · 9 downloadable styles").setView(scroll).setNegativeButton("Close",null).create();JSONArray fonts=catalog(activity);for(int i=0;i<fonts.length();i++){JSONObject f=fonts.optJSONObject(i);if(f==null)continue;File target=file(activity,f.optString("id"));Button choice=new Button(activity);choice.setText(f.optString("name")+(target.exists()?" · Use":" · Download "+String.format(Locale.US,"%.0f KB",f.optLong("bytes")/1024.0)));if(target.exists())choice.setTypeface(Typeface.createFromFile(target));choice.setOnClickListener(v->{if(target.exists()){applied.accept("file:"+target.getAbsolutePath());list.dismiss();return;}new AlertDialog.Builder(activity).setTitle("Download "+f.optString("name")+"?").setMessage("Requires internet. Download size: "+String.format(Locale.US,"%.0f KB",f.optLong("bytes")/1024.0)+". The font stays on this phone for offline use. Free under the SIL Open Font License.").setPositiveButton("Download",(d,w)->download(activity,f,()->{if(!activity.isFinishing()){applied.accept("file:"+target.getAbsolutePath());list.dismiss();}})).setNegativeButton("Cancel",null).setNeutralButton("License",(d,w)->license(activity,f.optString("license"))).show();});content.addView(choice);}list.show();}
 private static void license(Activity a,String path){try(InputStream in=a.getAssets().open(path)){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[4096];for(int n;(n=in.read(b))!=-1;)out.write(b,0,n);new AlertDialog.Builder(a).setTitle("SIL Open Font License").setMessage(out.toString("UTF-8")).setPositiveButton("Close",null).show();}catch(Exception e){Toast.makeText(a,"License unavailable",Toast.LENGTH_SHORT).show();}}
 private static void download(Activity a,JSONObject font,Runnable done){AtomicBoolean cancelled=new AtomicBoolean();Handler main=new Handler(Looper.getMainLooper());ProgressDialog progress=new ProgressDialog(a);progress.setTitle("Downloading "+font.optString("name"));progress.setMessage("You can cancel without adding this font.");progress.setProgressStyle(ProgressDialog.STYLE_HORIZONTAL);progress.setMax(100);progress.setCancelable(true);progress.setOnCancelListener(d->cancelled.set(true));progress.setButton(DialogInterface.BUTTON_NEGATIVE,"Cancel",(d,w)->cancelled.set(true));progress.show();new Thread(()->{File target=file(a,font.optString("id")),partial=null;HttpURLConnection connection=null;String failure=null;try{File dir=target.getParentFile();if(!dir.exists()&&!dir.mkdirs())throw new IOException("Font storage unavailable");partial=File.createTempFile("font-",".part",dir);URL url=new URL(font.getString("url"));if(!url.getProtocol().equals("https")||!url.getHost().equals("raw.githubusercontent.com"))throw new IOException("Untrusted font source");connection=(HttpURLConnection)url.openConnection();connection.setInstanceFollowRedirects(false);connection.setConnectTimeout(12000);connection.setReadTimeout(12000);if(connection.getResponseCode()!=200)throw new IOException("Download failed; try again with internet access");MessageDigest hash=MessageDigest.getInstance("SHA-256");long size=0,expected=font.getLong("bytes");try(InputStream in=connection.getInputStream();OutputStream out=new FileOutputStream(partial)){byte[] bytes=new byte[16384];for(int n;(n=in.read(bytes))!=-1;){if(cancelled.get())throw new IOException("Canceled");size+=n;if(size>expected||size>4*1024*1024)throw new IOException("Unexpected font size");hash.update(bytes,0,n);out.write(bytes,0,n);int percent=(int)(size*100/expected);main.post(()->{if(progress.isShowing())progress.setProgress(percent);});}}StringBuilder hex=new StringBuilder();for(byte b:hash.digest())hex.append(String.format(Locale.US,"%02x",b&255));if(size!=expected||!hex.toString().equals(font.getString("sha256")))throw new IOException("Font verification failed");Typeface.createFromFile(partial);if(cancelled.get())throw new IOException("Canceled");if(!partial.renameTo(target))throw new IOException("Cannot save font");}catch(Exception e){failure=e.getMessage();}finally{if(partial!=null)partial.delete();if(connection!=null)connection.disconnect();}String error=failure;main.post(()->{if(progress.isShowing())progress.dismiss();if(a.isFinishing()||a.isDestroyed())return;if(error==null&&!cancelled.get())done.run();else if(!cancelled.get())Toast.makeText(a,"Font: "+error,Toast.LENGTH_LONG).show();});},"optional-font-download").start();}
}
